-- Custom T4 tier (denysfast/bar-game): builds T4 unitdefs from existing T2/T3 unitdefs.
-- Used from units/*/T4/*.lua via VFS.Include; lives outside units/ so the unitdef loader does not
-- try to load it as a unit. See CUSTOM.md, section "T4".
--
-- A T4 unit = the base unit's model scaled up (objects3d/Units/T4/<name>.s3o, generated by
-- tools/t4/build_models.py - the engine cannot scale models at runtime), its script, sounds and
-- weapons, with:
--   * cost, buildtime, health scaled by `value` (T4 is to T3 roughly what T3 is to T1)
--   * weapon damage scaled by `damage`, range by `range`, area of effect by `aoe`
--   * footprint / collision volume / movement class sized for the bigger model

local T4 = {}

local function deepcopy(v)
	if type(v) ~= "table" then
		return v
	end
	local out = {}
	for k, x in pairs(v) do
		out[k] = deepcopy(x)
	end
	return out
end
T4.deepcopy = deepcopy

local function scaleVec(str, mult)
	if type(str) ~= "string" then
		return str
	end
	local parts = {}
	for n in str:gmatch("%S+") do
		parts[#parts + 1] = string.format("%.1f", (tonumber(n) or 0) * mult)
	end
	return table.concat(parts, " ")
end
T4.scaleVec = scaleVec

local function mulField(t, key, mult)
	if t[key] then
		t[key] = t[key] * mult
	end
end

-- load one unitdef table from a unit file
function T4.base(path, name)
	local defs = VFS.Include(path)
	return deepcopy(defs[name])
end

-- scale one weapondef in place
-- opts: damage, range, aoe, velocity (default sqrt(range) so ballistic weapons still reach), size
function T4.scaleWeapon(wd, opts)
	local damage = opts.damage or 1
	local range = opts.range or 1
	if wd.damage then
		for armor, v in pairs(wd.damage) do
			wd.damage[armor] = v * damage
		end
	end
	if wd.range and wd.range > 0 then
		wd.range = wd.range * range
	end
	mulField(wd, "areaofeffect", opts.aoe or 1)
	mulField(wd, "craterareaofeffect", opts.aoe or 1)
	local vel = opts.velocity or math.sqrt(range)
	mulField(wd, "weaponvelocity", vel)
	mulField(wd, "startvelocity", vel)
	mulField(wd, "flighttime", range / vel)
	mulField(wd, "size", opts.size or 1)
	mulField(wd, "thickness", opts.size or 1)
	mulField(wd, "corethickness", opts.size or 1)
	mulField(wd, "camerashake", opts.aoe or 1)
	if wd.customparams and wd.customparams.overrange_distance then
		wd.customparams.overrange_distance = wd.customparams.overrange_distance * range
	end
	return wd
end

-- build a T4 unitdef
-- p = { value, health, damage, range, aoe, scale, speed, footprint, movementclass, metalcost,
--       weapons = { <key> = { damage=, range=, aoe=, velocity=, ... override fields } },
--       overrides = { field = value, customparams = {...} } }
function T4.derive(base, p)
	local ud = deepcopy(base)
	ud.objectname = "Units/T4/" .. p.name .. ".s3o"
	local value = p.value
	local scale = p.scale or 2

	ud.metalcost = p.metalcost or math.floor(ud.metalcost * value)
	ud.energycost = math.floor((ud.energycost or 0) * value)
	ud.buildtime = math.floor((ud.buildtime or 0) * value)
	ud.health = math.floor(ud.health * (p.health or value))
	ud.mass = ud.metalcost
	ud.speed = (ud.speed or 0) * (p.speed or 0.75)
	mulField(ud, "maxacc", p.accel or 0.6)
	mulField(ud, "maxdec", p.accel or 0.6)
	mulField(ud, "turnrate", p.turn or 0.55)
	mulField(ud, "turninplacespeedlimit", p.speed or 0.75)
	ud.sightdistance = math.floor((ud.sightdistance or 400) * (p.sight or 1.6))
	if ud.airsightdistance then
		ud.airsightdistance = math.floor(ud.airsightdistance * (p.sight or 1.6))
	end
	ud.footprintx = p.footprint
	ud.footprintz = p.footprint
	ud.movementclass = p.movementclass
	ud.maxslope = nil -- the movement class decides
	ud.maxwaterdepth = nil
	ud.collisionvolumescales = scaleVec(ud.collisionvolumescales, scale)
	ud.collisionvolumeoffsets = scaleVec(ud.collisionvolumeoffsets, scale)
	ud.cantbetransported = true
	ud.explodeas = p.explodeas or "korgExplosion"
	ud.selfdestructas = p.selfdestructas or "korgExplosionSelfd"
	ud.selfdestructcountdown = 10

	local cp = ud.customparams or {}
	ud.customparams = cp
	cp.techlevel = 4
	cp.t4_scale = scale
	cp.unitgroup = cp.unitgroup or "weapon"
	cp.subfolder = "T4"
	cp.rangexpscale = nil -- the stock weapon-1 range bonus would stack on the hero levels
	if cp.customrange then
		cp.customrange = cp.customrange * (p.range or 1)
	end

	-- wreck: the scaled wreck model, its metal follows the new cost
	if ud.featuredefs then
		for fname, fd in pairs(ud.featuredefs) do
			if fd.metal then
				fd.metal = math.floor(ud.metalcost * (fname == "dead" and 0.55 or 0.22))
			end
			if fname == "dead" then
				fd.object = "Units/T4/" .. p.name .. "_dead.s3o"
				fd.collisionvolumescales = scaleVec(fd.collisionvolumescales, scale)
				fd.collisionvolumeoffsets = scaleVec(fd.collisionvolumeoffsets, scale)
				if fd.footprintx then
					fd.footprintx = math.floor(fd.footprintx * scale + 0.5)
					fd.footprintz = math.floor((fd.footprintz or fd.footprintx) * scale + 0.5)
				end
				mulField(fd, "height", scale)
			end
			if fd.damage then
				fd.damage = math.floor(fd.damage * value)
			end
		end
	end

	-- weapons: global multipliers, then per-weapon overrides
	if ud.weapondefs then
		for key, wd in pairs(ud.weapondefs) do
			local w = p.weapons and p.weapons[key] or {}
			T4.scaleWeapon(wd, {
				damage = w.damage or p.damage or value,
				range = w.range or p.range or 1,
				aoe = w.aoe or p.aoe or 1.5,
				velocity = w.velocity,
				size = w.size or math.sqrt(scale),
			})
			for field, v in pairs(w) do
				if field ~= "damage" and field ~= "range" and field ~= "aoe" and field ~= "velocity" and field ~= "size" then
					wd[field] = deepcopy(v)
				end
			end
		end
	end

	if p.overrides then
		for field, v in pairs(p.overrides) do
			if field == "customparams" then
				for k, x in pairs(v) do
					cp[k] = x
				end
			else
				ud[field] = deepcopy(v)
			end
		end
	end
	return ud
end

------------------------------------------------------------------------------- heroes
-- Every T4 is a hero (luarules/configs/t4_heroes.lua, luarules/gadgets/unit_t4_heroes.lua): one per
-- team, levels, talents, revive. T4.hero finishes a derived unitdef:
--   * maxthisunit = 1, customparams.t4_hero
--   * every CEG reference of its weapons and unit script scaled up by `fx` (gamedata/custom_t4_fx.lua)
--   * p.weapons: extra weapondefs "hero_*" the gadget spawns (swapped projectiles, meteors, novas);
--     they are not in the weapons list, the engine still registers them as <unit>_hero_*

local FX = VFS.Include("gamedata/custom_t4_fx.lua")
T4.FX = FX

local function scaleCegRefs(wd, fx)
	if wd.explosiongenerator then
		wd.explosiongenerator = FX.ref(wd.explosiongenerator, fx)
	end
	if wd.cegtag then
		wd.cegtag = FX.ref(wd.cegtag, fx)
	end
	if wd.customparams and wd.customparams.water_splash_ceg then
		wd.customparams.water_splash_ceg = FX.ref(wd.customparams.water_splash_ceg, fx)
	end
end

-- the hero design data (luarules/configs/t4_heroes.lua), loaded once; nil when it cannot load here
local heroH
local function heroConfig()
	if heroH == nil then
		local ok, res = pcall(VFS.Include, "luarules/configs/t4_heroes.lua")
		heroH = ok and res or false
		if not ok and Spring and Spring.Echo then
			Spring.Echo("[custom_t4] hero config not loaded: " .. tostring(res))
		end
	end
	return heroH or nil
end

-- v17: every T4 hero costs the same and is sized by its role (the cheap ones were paper, the expensive ones
-- tanks). T4.hero applies it first: cost, health, speed, and one damage
-- multiplier over its real weapons so their army DPS (damage x salvo x projectiles / reload x T4.armyFactor of the
-- blast; not paralyzers, aiming dummies or melee kicks under 150 range) meets `dps`. Level 1 values. v19: the
-- single-target DPS of a splash hero is lower than `dps` (Olympus ~2000, Starfall ~3200, Armageddon ~5100).
T4.HERO_COST = { metal = 100000, energy = 2000000, buildtime = 2500000 }
