-- an explosion-only weapon for Spring.SpawnExplosion (novas, flares)
function T4.novaWeapon(o)
	local w = T4.shellWeapon(o)
	w.name = o.name or "Hero nova"
	w.soundhit = o.soundhit or "nukearm"
	w.camerashake = o.aoe
	return w
end

