-- T4 foundry: the faction's T3 gantry at 1.5x, much more build power
function T4.foundry(base, p)
	local ud = deepcopy(base)
	ud.objectname = "Units/T4/" .. p.name .. ".s3o"
	local value = p.value or 12
	local scale = p.scale or 1.5
	ud.metalcost = math.floor(ud.metalcost * value)
	ud.energycost = math.floor(ud.energycost * value)
	ud.buildtime = math.floor(ud.buildtime * value)
	ud.health = math.floor(ud.health * 8)
	ud.workertime = math.floor(ud.workertime * (p.workertime or 12))
	local fp = math.floor((ud.footprintx or 12) * scale + 0.5)
	ud.footprintx = fp
	ud.footprintz = fp
	-- first half solid, second half yard (open build/exit area), like the T3 gantries
	local rows = {}
	for r = 1, fp do
		rows[r] = string.rep(r <= math.floor(fp / 2) and "o" or "e", fp)
	end
	ud.yardmap = table.concat(rows, " ")
	ud.collisionvolumescales = scaleVec(ud.collisionvolumescales, scale)
	ud.collisionvolumeoffsets = scaleVec(ud.collisionvolumeoffsets, scale)
	ud.buildoptions = p.buildoptions
	ud.maxthisunit = 1 -- one hero altar per team: it builds and revives the four heroes of its side
	ud.explodeas = "korgExplosion"
	ud.selfdestructas = "korgExplosionSelfd"
	local cp = ud.customparams or {}
	ud.customparams = cp
	cp.techlevel = 4
	cp.t4_scale = scale
	cp.unitgroup = "buildert4"
	cp.subfolder = "T4"
	if cp.buildinggrounddecalsizex then
		cp.buildinggrounddecalsizex = cp.buildinggrounddecalsizex * scale
		cp.buildinggrounddecalsizey = cp.buildinggrounddecalsizey * scale
	end
	if ud.featuredefs then
		for fname, fd in pairs(ud.featuredefs) do
			if fd.metal then
				fd.metal = math.floor(ud.metalcost * (fname == "dead" and 0.55 or 0.22))
			end
			if fname == "dead" then
				fd.object = "Units/T4/" .. p.name .. "_dead.s3o"
				fd.collisionvolumescales = scaleVec(fd.collisionvolumescales, scale)
				fd.collisionvolumeoffsets = scaleVec(fd.collisionvolumeoffsets, scale)
				if fd.footprintx then
					fd.footprintx = math.floor(fd.footprintx * scale + 0.5)
					fd.footprintz = math.floor((fd.footprintz or fd.footprintx) * scale + 0.5)
				end
				mulField(fd, "height", scale)
			end
		end
	end
	return ud
end

return T4
